public with sharing class AccountContactExplorerController {
    private static final Integer MAX_ROWS = 100;

    @AuraEnabled(cacheable=true)
    public static List<Account> getAccounts() {
        try {
            return [
                SELECT Id, Name
                FROM Account
                WITH USER_MODE
                ORDER BY Name
                LIMIT :MAX_ROWS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('An error occurred while retrieving accounts.');
        }
    }

    @AuraEnabled(cacheable=true)
    public static List<Contact> getContacts(Id accountId) {
        if (accountId == null) {
            return new List<Contact>();
        }

        try {
            return [
                SELECT Id, FirstName, LastName, Email, Phone
                FROM Contact
                WHERE AccountId = :accountId
                WITH USER_MODE
                ORDER BY LastName, FirstName
                LIMIT :MAX_ROWS
            ];
        } catch (Exception e) {
            throw new AuraHandledException('An error occurred while retrieving contacts.');
        }
    }
}

@IsTest
private class AccountContactExplorerControllerTest {
    @TestSetup
    static void setup() {
        Account acc = new Account(Name = 'Test Account');
        insert acc;

        insert new List<Contact>{
            new Contact(AccountId = acc.Id, FirstName = 'John', LastName = 'Doe', Email = 'john@example.com', Phone = '1234567890'),
            new Contact(AccountId = acc.Id, FirstName = 'Jane', LastName = 'Smith', Email = 'jane@example.com', Phone = '0987654321')
        };
    }

    @IsTest
    static void testGetAccounts() {
        Test.startTest();
        List<Account> results = AccountContactExplorerController.getAccounts();
        Test.stopTest();
        System.assertNotEquals(0, results.size(), 'Should return accounts');
    }

    @IsTest
    static void testGetContactsPopulated() {
        Account acc = [SELECT Id FROM Account LIMIT 1];
        Test.startTest();
        List<Contact> results = AccountContactExplorerController.getContacts(acc.Id);
        Test.stopTest();
        System.assertEquals(2, results.size(), 'Should return 2 contacts');
        System.assertEquals('Doe', results[0].LastName, 'Should be ordered by LastName');
    }

    @IsTest
    static void testGetContactsEmpty() {
        Account acc = new Account(Name = 'Empty Account');
        insert acc;
        Test.startTest();
        List<Contact> results = AccountContactExplorerController.getContacts(acc.Id);
        Test.stopTest();
        System.assertEquals(0, results.size(), 'Should return empty list for account without contacts');
    }

    @IsTest
    static void testGetContactsNull() {
        Test.startTest();
        List<Contact> results = AccountContactExplorerController.getContacts(null);
        Test.stopTest();
        System.assertEquals(0, results.size(), 'Should return empty list for null selection');
    }
}

import { describe, it, expect, jest, beforeEach } from '@jest/globals';
import { createElement } from 'lwc';
import AccountContactExplorer from 'c/accountContactExplorer';
import { getAccounts, getContacts } from '@salesforce/apex/AccountContactExplorerController';

jest.mock('@salesforce/apex/AccountContactExplorerController', () => ({
    getAccounts: { virtual: true, default: jest.fn() },
    getContacts: { virtual: true, default: jest.fn() }
}), { virtual: true });

const MOCK_ACCOUNTS = [
    { Id: 'acc1', Name: 'Account One' },
    { Id: 'acc2', Name: 'Account Two' }
];

const MOCK_CONTACTS = [
    { Id: 'con1', FirstName: 'First', LastName: 'One', Email: 'one@test.com', Phone: '111' },
    { Id: 'con2', FirstName: 'First', LastName: 'Two', Email: 'two@test.com', Phone: '222' }
];

describe('c-account-contact-explorer', () => {
    let element;

    beforeEach(() => {
        element = createElement('c-account-contact-explorer', { is: AccountContactExplorer });
        jest.clearAllMocks();
    });

    it('renders account options including blank option', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        document.body.appendChild(element);
        await Promise.resolve();

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        const options = combo.querySelectorAll('option');
        expect(options[0].value).toBe('');
        expect(options.length).toBe(3);
    });

    it('disables load button for blank selection and enables for valid selection', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        document.body.appendChild(element);
        await Promise.resolve();

        const loadBtn = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        expect(loadBtn.disabled).toBe(true);

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combo.value = 'acc1';
        combo.dispatchEvent(new Event('change'));
        await Promise.resolve();

        expect(loadBtn.disabled).toBe(false);
    });

    it('loads and renders contacts successfully', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        getContacts.mockResolvedValue(MOCK_CONTACTS);
        document.body.appendChild(element);
        await Promise.resolve();

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combo.value = 'acc1';
        combo.dispatchEvent(new Event('change'));

        const loadBtn = element.shadowRoot.querySelector('[data-role="load-contacts"]');
        loadBtn.click();

        await Promise.resolve();
        await Promise.resolve();

        const results = element.shadowRoot.querySelector('[data-role="contact-results"]');
        expect(results).not.toBeNull();
        expect(results.textContent).toContain('First One');
    });

    it('handles stale responses by ignoring late results', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        document.body.appendChild(element);
        await Promise.resolve();

        let resolveFirst;
        const firstPromise = new Promise(res => { resolveFirst = res; });
        getContacts.mockReturnValueOnce(firstPromise);

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combo.value = 'acc1';
        combo.dispatchEvent(new Event('change'));

        element.shadowRoot.querySelector('[data-role="load-contacts"]').click();

        // Change selection immediately to invalidate first request
        combo.value = 'acc2';
        combo.dispatchEvent(new Event('change'));

        getContacts.mockResolvedValueOnce([{ Id: 'con3', FirstName: 'New', LastName: 'User' }]);
        element.shadowRoot.querySelector('[data-role="load-contacts"]').click();

        // Resolve the first (stale) request
        resolveFirst(MOCK_CONTACTS);
        await Promise.resolve();

        const results = element.shadowRoot.querySelector('[data-role="contact-results"]');
        // Should not contain MOCK_CONTACTS because it was stale
        expect(results.textContent).not.toContain('First One');
    });

    it('shows guidance and clears state when selection is reset to blank', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        getContacts.mockResolvedValue(MOCK_CONTACTS);
        document.body.appendChild(element);
        await Promise.resolve();

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combo.value = 'acc1';
        combo.dispatchEvent(new Event('change'));
        element.shadowRoot.querySelector('[data-role="load-contacts"]').click();
        await Promise.resolve();
        await Promise.resolve();

        combo.value = '';
        combo.dispatchEvent(new Event('change'));
        await Promise.resolve();

        const alert = element.shadowRoot.querySelector('[role="alert"]');
        expect(alert).not.toBeNull();
        expect(element.shadowRoot.querySelector('[data-role="contact-results"]')).toBeNull();
    });

    it('renders error state on Apex failure', async () => {
        getAccounts.mockResolvedValue(MOCK_ACCOUNTS);
        getContacts.mockRejectedValue(new Error('Apex Error'));
        document.body.appendChild(element);
        await Promise.resolve();

        const combo = element.shadowRoot.querySelector('[data-role="account-selector"]');
        combo.value = 'acc1';
        combo.dispatchEvent(new Event('change'));
        element.shadowRoot.querySelector('[data-role="load-contacts"]').click();

        await Promise.resolve();
        await Promise.resolve();

        const alert = element.shadowRoot.querySelector('[role="alert"]');
        expect(alert).not.toBeNull();
        expect(element.shadowRoot.querySelector('[data-role="contact-results"]')).toBeNull();
    });
});

import { LightningElement, wire, track } from 'lwc';
import getAccounts from '@salesforce/apex/AccountContactExplorerController.getAccounts';
import getContacts from '@salesforce/apex/AccountContactExplorerController.getContacts';

export default class AccountContactExplorer extends LightningElement {
    @track selectedAccountId = '';
    @track accountOptions = [];
    @track contacts = null;
    @track isLoading = false;
    @track errorMessage = '';

    requestId = 0;

    columns = [
        { label: 'First Name', fieldName: 'FirstName' },
        { label: 'Last Name', fieldName: 'LastName' },
        { label: 'Email', fieldName: 'Email', type: 'email' },
        { label: 'Phone', fieldName: 'Phone', type: 'phone' }
    ];

    @wire(getAccounts)
    wiredAccounts({ error, data }) {
        if (data) {
            this.accountOptions = [
                { label: '-- Select an account --', value: '' },
                ...data.map(acc => ({ label: acc.Name, value: acc.Id }))
            ];
        } else if (error) {
            this.errorMessage = 'Failed to load accounts.';
        }
    }

    get isLoadDisabled() {
        return this.selectedAccountId === '';
    }

    get selectionGuidance() {
        return (this.selectedAccountId === '' && !this.isLoading) 
            ? 'Please select an account to load contacts.' 
            : '';
    }

    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    handleAccountChange(event) {
        this.selectedAccountId = event.detail.value;
        this.requestId++;
        this.contacts = null;
        this.isLoading = false;
        this.errorMessage = '';
    }

    async handleLoadContacts() {
        const currentRequestId = ++this.requestId;
        this.isLoading = true;
        this.errorMessage = '';
        this.contacts = null;

        try {
            const data = await getContacts({ accountId: this.selectedAccountId });
            if (currentRequestId === this.requestId) {
                this.contacts = data;
                this.isLoading = false;
            }
        } catch (error) {
            if (currentRequestId === this.requestId) {
                this.errorMessage = error.body?.message || 'An error occurred while loading contacts.';
                this.isLoading = false;
            }
        }
    }
}
